import heapq

CAP_A = 753
CAP_B = 357
TARGET = 159

def solve(transfer_only=True):
    INF = float('inf')
    dist = {}
    parent = {}

    start = (0, 0)
    dist[start] = 0
    pq = [(0, 0, 0)]  # (cost, a, b)

    while pq:
        cost, a, b = heapq.heappop(pq)

        if a == TARGET:
            path = []
            state = (a, b)
            while state != start:
                path.append(parent[state])
                state = parent[state][0]
            path.reverse()
            return cost, path

        if cost > dist.get((a, b), INF):
            continue

        moves = []

        # CHARGE A
        if a < CAP_A:
            mc = 0 if transfer_only else CAP_A
            moves.append(("CHARGE A", CAP_A, b, mc))

        # CHARGE B
        if b < CAP_B:
            mc = 0 if transfer_only else CAP_B
            moves.append(("CHARGE B", a, CAP_B, mc))

        # DRAIN A
        if a > 0:
            mc = 0 if transfer_only else a
            moves.append(("DRAIN A", 0, b, mc))

        # DRAIN B
        if b > 0:
            mc = 0 if transfer_only else b
            moves.append(("DRAIN B", a, 0, mc))

        # TRANSFER A B
        if a > 0 and b < CAP_B:
            transfer = min(a, CAP_B - b)
            if transfer > 0:
                moves.append(("TRANSFER A B", a - transfer, b + transfer, transfer))

        # TRANSFER B A
        if b > 0 and a < CAP_A:
            transfer = min(b, CAP_A - a)
            if transfer > 0:
                moves.append(("TRANSFER B A", a + transfer, b - transfer, transfer))

        for name, na, nb, mcost in moves:
            new_cost = cost + mcost
            if new_cost < dist.get((na, nb), INF):
                dist[(na, nb)] = new_cost
                parent[(na, nb)] = ((a, b), name, mcost)
                heapq.heappush(pq, (new_cost, na, nb))

    return None

print("=== Transfer only ===")
result = solve(transfer_only=True)
if result:
